/**
 * usePriceTicker.ts
 *
 * Builds price chart data from two sources:
 *
 *   1. Historical (localhost only):
 *      queryFilter MockPriceFeed.PriceUpdated(token) from block 0 to latest.
 *      This gives the seeded price history generated by seed-price-history.js.
 *
 *   2. Real-time (all networks):
 *      Polls vault.getMinPrice(indexToken) every 10 seconds and appends new ticks.
 *
 * Both sources produce TradeEvent[] with sizeDelta=0 — they affect only the
 * candlestick Price chart, not OI or Funding Rate charts.
 */

import { Contract, formatEther } from "ethers";
import { useEffect, useState } from "react";

import { getProvider } from "lib/rpc";
import { getVantageContractAddress } from "vantage/contracts";
import localhostDeployment from "vantage/deployments/frontend-localhost.json";
import { Vault__factory } from "vantage/types";

import type { TradeEvent } from "./types";

const POLL_INTERVAL_MS = 10_000; // 10 seconds
const LOCALHOST_CHAIN_ID = 31337;
const ZERO = "0x0000000000000000000000000000000000000000";

// Minimal ABI for querying MockPriceFeed.PriceUpdated events
const PRICE_UPDATED_ABI = ["event PriceUpdated(address indexed token, uint256 price, uint256 timestamp)"];

const MOCK_PRICE_FEED = (localhostDeployment.addresses as { MockPriceFeed?: string }).MockPriceFeed ?? "";

export function usePriceTicker(chainId: number, indexToken: string, vaultAddress?: string): TradeEvent[] {
  const [ticks, setTicks] = useState<TradeEvent[]>([]);

  useEffect(() => {
    if (!indexToken) return;

    let resolvedVaultAddress: string;
    try {
      resolvedVaultAddress = vaultAddress ?? getVantageContractAddress(chainId, "JuniorTrancheVault");
    } catch {
      return;
    }
    if (!resolvedVaultAddress || resolvedVaultAddress === ZERO) return;

    const provider = getProvider(undefined, chainId);
    const vault = Vault__factory.connect(resolvedVaultAddress, provider);

    let cancelled = false;

    async function loadHistory() {
      // Only localhost has MockPriceFeed with PriceUpdated events
      if (chainId !== LOCALHOST_CHAIN_ID || !MOCK_PRICE_FEED) return;

      try {
        const feed = new Contract(MOCK_PRICE_FEED, PRICE_UPDATED_ABI, provider);
        const filter = feed.filters.PriceUpdated(indexToken);
        const logs = await feed.queryFilter(filter, 0, "latest");

        const historical: TradeEvent[] = logs.map((log) => {
          const parsed = feed.interface.parseLog({ topics: [...log.topics], data: log.data });
          return {
            price: parseFloat(formatEther(parsed!.args.price as bigint)),
            sizeDelta: 0,
            isLong: true,
            timestamp: Number(parsed!.args.timestamp as bigint),
            type: "increase" as const,
          };
        });

        if (!cancelled && historical.length > 0) {
          setTicks(historical);
        }
      } catch {
        // History unavailable — real-time polling will still work
      }
    }

    async function tick() {
      try {
        const raw = await vault.getMinPrice(indexToken);
        const price = parseFloat(formatEther(raw));
        if (price <= 0 || cancelled) return;

        const event: TradeEvent = {
          price,
          sizeDelta: 0,
          isLong: true,
          timestamp: Math.floor(Date.now() / 1000),
          type: "increase",
        };

        setTicks((prev) => [...prev, event]);
      } catch {
        // Price feed unavailable — skip this tick silently
      }
    }

    loadHistory();
    tick(); // Initial fetch immediately
    const timer = setInterval(tick, POLL_INTERVAL_MS);

    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [chainId, indexToken, vaultAddress]); // eslint-disable-line react-hooks/exhaustive-deps

  return ticks;
}
